import { test } from "node:test";
import assert from "node:assert/strict";
import { hashPassword } from "../src/auth/passwords.ts";
import { LoginThrottle } from "../src/auth/throttle.ts";
import { loginService, type Employee } from "../src/auth/login.ts";
import { loginHandler } from "../src/auth/http.ts";

const PASSWORD = "correct horse battery staple";

function setup() {
    const employees: Employee[] = [
        { id: "e1", username: "dana.reyes", passwordHash: hashPassword(PASSWORD), disabled: false },
        { id: "e2", username: "former.staff", passwordHash: hashPassword(PASSWORD), disabled: true },
    ];
    const directory = { findByUsername: async (u: string) => employees.find((e) => e.username === u) ?? null };
    let issued = 0;
    const sessions = { issue: async (id: string) => `sess-${id}-${++issued}` };
    const clock = { t: 1_000_000 };
    const throttle = new LoginThrottle({ maxFailures: 5, windowMs: 15 * 60_000, lockMs: 30 * 60_000 });
    const service = loginService(directory, throttle, sessions, () => clock.t);
    return { service, http: loginHandler(service), clock };
}

test("the right password signs the employee in, whatever case they type", async () => {
    const { service } = setup();
    const res = await service.login("  Dana.Reyes ", PASSWORD);
    assert.equal(res.ok, true);
    assert.equal(res.ok && res.employeeId, "e1");
});

test("a wrong password and an unknown user get the same 401", async () => {
    const { http } = setup();
    const wrong = await http({ username: "dana.reyes", password: "hunter2" });
    const unknown = await http({ username: "nobody", password: "hunter2" });
    assert.deepEqual([wrong.status, wrong.body], [401, { error: "invalid username or password" }]);
    assert.deepEqual([unknown.status, unknown.body], [wrong.status, wrong.body]);
});

test("five failures lock the account, even against the right password", async () => {
    const { service } = setup();
    for (let i = 0; i < 5; i++) await service.login("dana.reyes", `guess-${i}`);
    const res = await service.login("dana.reyes", PASSWORD);
    assert.equal(res.ok, false);
    assert.equal(!res.ok && res.reason, "locked");
});

test("changing the case of the username doesn't reset the failure count", async () => {
    const { service } = setup();
    const spellings = ["dana.reyes", "Dana.Reyes", "DANA.REYES", "dana.REYES", "Dana.reyes", "dAna.reyes"];
    const reasons = [];
    for (const [i, name] of spellings.entries()) {
        const res = await service.login(name, `guess-${i}`);
        reasons.push(res.ok ? "ok" : res.reason);
    }
    console.log("results for six guesses with varied casing:", reasons);
    assert.equal(reasons[5], "locked");
    const res = await service.login("DaNa.ReYeS", PASSWORD);
    assert.equal(res.ok, false);
});

test("padding the username with spaces doesn't get around a lock", async () => {
    const { service } = setup();
    for (let i = 0; i < 5; i++) await service.login("dana.reyes", `guess-${i}`);
    const res = await service.login(" dana.reyes ", PASSWORD);
    assert.equal(res.ok ? "signed in" : res.reason, "locked");
});

test("the lock expires, and a successful login clears earlier failures", async () => {
    const { service, clock } = setup();
    for (let i = 0; i < 5; i++) await service.login("dana.reyes", `guess-${i}`);
    clock.t += 30 * 60_000;
    assert.equal((await service.login("dana.reyes", PASSWORD)).ok, true);
    for (let i = 0; i < 4; i++) await service.login("dana.reyes", `guess-${i}`);
    assert.equal((await service.login("dana.reyes", PASSWORD)).ok, true);
});

test("a locked account gets 429 with Retry-After over HTTP, however it is spelled", async () => {
    const { http, clock } = setup();
    for (let i = 0; i < 5; i++) await http({ username: i % 2 ? "DANA.REYES" : "dana.reyes", password: `guess-${i}` });
    clock.t += 60_000;
    const res = await http({ username: "Dana.Reyes", password: PASSWORD });
    assert.equal(res.status, 429);
    assert.equal(res.headers["Retry-After"], String(29 * 60));
});

test("a disabled employee can't sign in with a correct password", async () => {
    const { http } = setup();
    const res = await http({ username: "former.staff", password: PASSWORD });
    assert.equal(res.status, 401);
    assert.equal(res.headers["Set-Cookie"], undefined);
});
